// Prompt Mühendisliği cheat sheet. 12 konu; kod sütununda prompt kalıpları.
import type { Topic } from './types'

export const promptGiris: { q: string; a: string }[] = [
  { q: 'Prompt nedir?', a: 'Yapay zeka modeline yazdığın mesajın tamamı: talimat, açıklama, örnek, yüklediğin metin. Kelime İngilizce "ipucu, yönlendirme" demek. ChatGPT\'ye "bana bir e-posta yaz" yazdığında bir prompt yazmış oldun. Modelin cevabı büyük ölçüde bu mesajın ne kadar iyi olduğuna bağlıdır.' },
  { q: 'Prompt mühendisliği ne demek, neden böyle havalı bir adı var?', a: 'İstediğin sonucu her seferinde güvenilir biçimde almak için mesajını bilinçli tasarlamak, denemek ve düzeltmek. Adı abartılı; aslında "iyi iş tarif etme" becerisidir. Yeni bir çalışana işi anlatmak gibi: ne kadar net, bağlamlı ve örnekli anlatırsan o kadar iyi sonuç alırsın.' },
  { q: 'Model benim ne istediğimi anlamıyor mu, neden bu kadar uğraşayım?', a: 'Model aklını okuyamaz; sadece yazdığına bakar. "Özet çıkar" dersen kime, ne uzunlukta, hangi vurguyla olduğunu bilmez ve kendi varsayımıyla doldurur. Belirsizlik bıraktığın her yeri model tahminle doldurur; tahmin seninkiyle örtüşmeyince "kötü cevap" alırsın. Aynı model, iyi promptla bambaşka sonuç verir.' },
  { q: 'Kod bilmem gerekiyor mu?', a: 'Hayır. Bu bölümdeki her şey ChatGPT, Claude, Gemini gibi sohbet arayüzlerinde doğrudan yazarak uygulanır. Soldaki "kod" sütununda gördüğün şeyler prompt kalıplarıdır, program değil. Uygulama geliştirenler aynı kalıpları koda taşır; o ayrı başlık (LLM API Kullanımı).' },
  { q: 'Model aslında nasıl "düşünüyor"?', a: 'Düşünmüyor; yazdığın metnin devamında en olası kelime parçasını tahmin ediyor ve bunu tekrarlıyor. Bu yüzden prompttaki her şey (rol, örnek, biçim, ton) tahmini yönlendirir. Prompta "sen bir doktorsun" yazınca tıp metinlerine benzer devamlar olasılaşır. Temeller bölümünde bunu ayrıntılı anlattık.' },
  { q: 'Model neden bazen uyduruyor?', a: 'Çünkü "doğru" değil "olası" metin üretir. Olmayan bir kaynağı, yanlış bir tarihi akıcı biçimde yazabilir; buna halüsinasyon denir. Promptla azaltılır: "sadece verdiğim belgeye dayan", "bilmiyorsan bilmiyorum de" gibi çıkış yolları tanırsın. Yine de önemli bilgiyi her zaman kontrol edersin.' },
  { q: 'İyi prompt ile kötü prompt arasındaki fark somut olarak ne?', a: 'Kötü: "Bu metni özetle." İyi: "Bu metni, konuyu bilmeyen bir yönetici için 3 maddede, her madde en fazla 15 kelime olacak şekilde özetle; sayıları koru." İkincisinde kitle, uzunluk, biçim ve vurgu var. Model artık tahmin etmez, uygular.' },
  { q: 'Hangi modelde hangi kalıp çalışır?', a: 'Kalıpların hepsi tüm modellerde çalışır: net görev, bağlam, örnek, biçim, rol. Küçük farklar var: Claude XML etiketlerini (<belge>...</belge>) iyi anlar, GPT markdown başlıklarını sever. Bu bölümdeki her şey modelden bağımsızdır.' },
  { q: 'Sistem mesajı ne demek?', a: 'Sohbetin başında bir kez verilen ve tüm konuşma boyunca geçerli kalan talimat. "Sen bir Türkçe dil bilgisi asistanısın, sadece bu konuda yardım et" gibi. ChatGPT\'de "özel talimatlar" ve GPT\'ler, Claude\'da Projects aynı işi görür. Kendi asistanını kurarken burayı yazarsın.' },
  { q: 'Görsel üreten araçlara da prompt yazılıyor; aynı mı?', a: 'Mantık aynı ama dil farklı. Dil modeline cümle yazarsın; görsel modele (Midjourney, Stable Diffusion) kısa, virgülle ayrılmış, çoğunlukla İngilizce anahtar kelimeler yazarsın: konu, stil, ışık, kamera. Bu bölümün medya konusunda ayrıntı var.' },
  { q: 'Yazdığım prompt iyi mi, nasıl anlarım?', a: 'Deneyerek. Çıktıya bak, beğenmediğin yeri bul, o eksikliği prompta kısıt olarak ekle, tekrar dene. Buna iterasyon denir ve prompt yazmanın normal halidir; ilk deneme nadiren sondur. Uygulamada kullanacaksan 20-50 örnekten oluşan küçük bir test setiyle ölçersin.' },
  { q: 'Hangi sırayla öğrenmeliyim?', a: 'Soldaki sıra öğrenme sırasıdır: önce Temel İlkeler ve Prompt Yapısı (en büyük fark burada), sonra Rol, Örnekli Prompt, Akıl Yürütme, Çıktı Biçimi. Sistem Mesajı ve Test konuları uygulama kuracaklar için. Hazır Kalıplar ve Günlük İş Akışları ise hemen kopyalayıp kullanabileceğin reçeteler.' },
  { q: 'Bu bölümü bitirince ne yapabileceğim?', a: 'Yazı, özet, çeviri, e-posta, kod, analiz gibi günlük işleri modele doğru tarif edip ilk denemede kullanılabilir sonuç alabileceksin. Uydurmayı fark edecek, gizli veri göndermemeyi bilecek, kendi prompt kütüphaneni kurmuş olacaksın. Bu, yapay zekayı "deneyen" ile "işine katan" arasındaki farktır.' },
]

